// QA joint for the client-relayed-fetch transport (box 7.1, Tier 1). The REAL
// composed graph runs as subprocesses — the server binary, the six plugins,
// and the shikimori child — with MELLIFERA_SHIKIMORI_UPSTREAM dead-pinned to a
// closed loopback port (the qa_plugin_logs precedent: even an accidental fetch
// cannot leave the machine, and the refusal is instant). A real scan drives an
// enrichment run into the DEFERRED outcome: the shikimori fetch classifies
// network, the whole request plan hands to the relay queue as one durable job,
// the 'relayed' ledger row lands, and the series still settles ready (a
// deferred pair in cooldown is terminal-at-settle).
//
// The client role is then played by a PAIRED DEVICE TOKEN minted through the
// real pairing flow over the same subprocess (the any-authenticated-principal
// ruling OQ-1, proven with a non-admin credential): POST /relay/claim takes
// the descriptor (its URL carries the dead upstream — the handoff proof), the
// test executes the descriptor VERBATIM (the connection must fail), and the
// canned shikimori search body replaces the fetch exactly the way a browser
// with network access would answer: POST /relay/{id}/result with http 200.
// The completion wake (Ingest → ClearFailure → Queue.Notify) re-derives the
// pair, the consult feeds the stored response in as the primary, and the
// notified derivation lands sources.shikimori with the _stages fetch entry
// stamped executor:"client" while the ledger row clears.
//
// Every helper is qaRelay-prefixed to stay collision-free in package
// mellifera_test; the shared harness (buildBinary/doRequest/scanLibrary/…)
// and the qaSerial server/boot/settle helpers are reused as-is.
package itest

import (
	"encoding/base64"
	"encoding/json"
	"net/http"
	"net/url"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"
)

// Fixture identity + transport constants. The library/directory names are
// independent of every other suite's fixtures (no-coincidence discipline);
// "Relay Beacon S01" derives the search title "Relay Beacon" (season 1) under
// the shared grammar's season-marker cut. The dead upstream is a CLOSED
// loopback port — dial refused instantly, classified network.
const (
	qaRelayDir          = "Relay Beacon S01"
	qaRelayEpRel        = qaRelayDir + "/Relay Beacon S01E01.mkv"
	qaRelayTitle        = "Relay Beacon"
	qaRelayAdminToken   = "qa-relay-admin-token"
	qaRelayDeadUpstream = "http://127.0.0.1:9"
	// The canned candidate's anchor id — far from any real upstream assignment
	// and from every other suite's fixture ids.
	qaRelayAnimeID = 931
)

// qaRelayWaitTimeout bounds the two async waits (the relayed ledger row
// landing, and the notified derivation landing the namespace + clearing the
// row). Each is a sub-second round trip in practice; 60s is generous and
// bounded (INV-poll-bounded).
const qaRelayWaitTimeout = 60 * time.Second

// TestRelayJoint is the Tier-1 joint round trip of the relay transport — ONE
// test function; every sub-assert lives inside it.
func TestRelayJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("QA relay joint: skips under -short (builds binaries + subprocesses)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — the episode cannot be probed; skipping the relay joint (INV4: optional binary)")
	}
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skip("ffmpeg not on PATH — cannot generate the media fixture the library requires")
	}

	tmp := t.TempDir()
	srvBins := qaSerialServerBins{
		server:        buildBinary(t, tmp, "qa-relay-server", "./cmd/mellifera"),
		baseScanner:   buildBinary(t, tmp, "qa-relay-basescanner", "./plugins/base-scanner"),
		tvParser:      buildBinary(t, tmp, "qa-relay-tvparser", "./plugins/tv-parser"),
		imageEnricher: buildBinary(t, tmp, "qa-relay-imageenricher", "./plugins/image-enricher"),
		serialScanner: buildBinary(t, tmp, "qa-relay-scanner", "./plugins/serial-scanner"),
		serialParser:  buildBinary(t, tmp, "qa-relay-parser", "./plugins/serial-parser"),
		frameGrabber:  buildBinary(t, tmp, "qa-relay-grabber", "./plugins/frame-grabber"),
	}

	// The server boots with the shikimori upstream dead-pinned (the env seam
	// resolves once at the plugin child's process start and bakes into every
	// fetch template — the descriptor's URL will carry it).
	root := qaRelayWriteFixtures(t)
	srv := qaSerialStartServer(t, srvBins, qaRelayDeadUpstream, tmp, qaRelayAdminToken)
	client := &http.Client{Timeout: httpTimeout}

	// --- the run defers: scan → drain → relayed ledger row ---
	lib := qaSerialCreateLibrary(t, client, srv.baseURL, qaRelayAdminToken, root, "QA Relay Joint")
	res := scanLibrary(t, client, srv.baseURL, qaRelayAdminToken, lib)
	if res.Discovered != 2 || res.Persisted != 2 {
		t.Fatalf("QA relay library: scan discovered=%d persisted=%d, want 2/2 (1 serial record + 1 episode); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	if len(res.Warnings) != 0 {
		t.Errorf("QA relay library: warnings = %v, want none (no deep videos)", res.Warnings)
	}
	// The series settles READY despite the deferral: serial-parser wrote, the
	// shikimori pair is relayed-cooldown — terminal-at-settle, never stuck.
	qaSerialWaitSettled(t, client, srv.baseURL, qaRelayAdminToken, lib)

	series := qaSerialListSeries(t, client, srv.baseURL, qaRelayAdminToken, lib)
	if len(series) != 1 {
		t.Fatalf("QA relay library: series count = %d, want exactly the one serial record", len(series))
	}
	sr := series[0]
	if sr.Status != "ready" {
		t.Errorf("series %q status = %q after the deferred run, want ready (a relayed pair is terminal-at-settle)", sr.RelativePath, sr.Status)
	}
	doc := parseAsyncDoc(t, qaSerialSeriesDocument(t, client, srv.baseURL, qaRelayAdminToken, sr.ID))
	if doc.Sources["shikimori"] != nil {
		t.Fatalf("series %q: sources.shikimori = %v after the deferred run, want ABSENT (the deferral must not land a namespace)", sr.RelativePath, doc.Sources["shikimori"])
	}
	deferred := qaRelayStage(doc.Stages, "deferred")
	if deferred == nil {
		t.Fatalf("series %q: no deferred shikimori stage in _stages %v (the run must end deferred against the dead upstream)", sr.RelativePath, doc.Stages)
	}
	if got := asyncStr(deferred, "class"); got != "network" {
		t.Errorf("deferred stage class = %q, want network (the machine class of the dial refusal)", got)
	}

	// The relayed ledger row the handoff wrote — the loop-safety write.
	row := qaRelayWaitFailure(t, client, srv.baseURL, qaRelayAdminToken, sr.ID, true)
	if row.PluginID != "shikimori" {
		t.Errorf("relayed ledger row plugin_id = %q, want shikimori", row.PluginID)
	}
	if row.Status != "relayed" {
		t.Errorf("relayed ledger row status = %q, want relayed (the handoff's quiet-down)", row.Status)
	}
	if !strings.HasPrefix(row.Reason, "network: ") {
		t.Errorf("relayed ledger row reason = %q, want the \"network: <text>\" shape Enqueue writes", row.Reason)
	}

	// --- the client role: a REAL paired device token ---
	deviceToken := qaRelayPairDevice(t, client, srv.baseURL)

	// --- claim: the descriptor carries the dead upstream (the handoff proof) ---
	var claim qaRelayClaim
	if status := doRequest(t, client, http.MethodPost, srv.baseURL+"/api/v1/relay/claim", deviceToken, nil, &claim); status != http.StatusOK {
		t.Fatalf("POST /relay/claim (device token): HTTP %d, want 200 (any authenticated principal may claim, OQ-1)", status)
	}
	if claim.Purpose != "enrich" {
		t.Errorf("claim purpose = %q, want enrich", claim.Purpose)
	}
	if len(claim.Plan) != 1 {
		t.Fatalf("claim plan = %+v, want exactly the one search spec (a search stays single-fetch)", claim.Plan)
	}
	spec := claim.Plan[0]
	if spec.Method != http.MethodGet {
		t.Errorf("descriptor method = %q, want GET", spec.Method)
	}
	if !strings.HasPrefix(spec.URL, qaRelayDeadUpstream) {
		t.Fatalf("descriptor url = %q, want the dead upstream origin %q (the server-authored handoff, not a lucky server fetch)", spec.URL, qaRelayDeadUpstream)
	}
	// The core percent-encodes substituted variables (url.QueryEscape), so the
	// space in the derived title rides as '+' in the descriptor.
	if !strings.Contains(spec.URL, "search="+url.QueryEscape(qaRelayTitle)) {
		t.Errorf("descriptor url = %q, want the derived search title %q carried (query-escaped)", spec.URL, qaRelayTitle)
	}

	// --- execute the descriptor VERBATIM: the connection must fail ---
	req, err := http.NewRequest(spec.Method, spec.URL, nil)
	if err != nil {
		t.Fatalf("build descriptor request: %v", err)
	}
	for k, v := range spec.Headers {
		req.Header.Set(k, v)
	}
	resp, err := client.Do(req)
	if err == nil {
		if resp != nil {
			resp.Body.Close()
		}
		t.Fatalf("descriptor executed against %s SUCCEEDED — the upstream port is not dead, the joint premise is broken", spec.URL)
	}

	// --- answer with the canned shikimori body (a browser with network
	// access would return exactly this shape; the canned body replaces the
	// fetch) ---
	canned, err := json.Marshal(qaRelayCannedSearch())
	if err != nil {
		t.Fatalf("marshal canned body: %v", err)
	}
	result := map[string]any{
		"http_status": http.StatusOK,
		"headers":     map[string]string{"Content-Type": "application/json"},
		"body":        base64.StdEncoding.EncodeToString(canned),
	}
	if status := doRequest(t, client, http.MethodPost, srv.baseURL+"/api/v1/relay/"+strconv.FormatInt(claim.ID, 10)+"/result", deviceToken, result, nil); status != http.StatusNoContent {
		t.Fatalf("POST /relay/%d/result: HTTP %d, want 204 (the outcome accepted)", claim.ID, status)
	}

	// --- the notified derivation: consult hit → namespace lands, stamped ---
	doc = qaRelayWaitShikimori(t, client, srv.baseURL, qaRelayAdminToken, sr.ID)
	ns := doc.Sources["shikimori"]
	title, _ := ns["title"].(map[string]any)
	if asyncStr(title, "romaji") != qaRelayTitle || asyncStr(title, "russian") != "Релейный маяк" {
		t.Errorf("sources.shikimori.title = %v, want {romaji:%s russian:Релейный маяк} (the canned candidate, RU-first)", title, qaRelayTitle)
	}
	if asyncStr(ns, "kind") != "tv" {
		t.Errorf("sources.shikimori.kind = %v, want tv (the canned kind)", ns["kind"])
	}
	if got := asyncStr(ns, "url"); !strings.HasPrefix(got, qaRelayDeadUpstream) {
		t.Errorf("sources.shikimori.url = %q, want the absolute url against the dead upstream (the payload flowed through the relay, not a server fetch)", got)
	}
	var fullDoc map[string]any
	if err := json.Unmarshal(qaSerialSeriesDocument(t, client, srv.baseURL, qaRelayAdminToken, sr.ID), &fullDoc); err != nil {
		t.Fatalf("decode final document: %v", err)
	}
	ids, _ := fullDoc["identifiers"].(map[string]any)
	if got, _ := ids["shikimori_id"].(float64); int(got) != qaRelayAnimeID {
		t.Errorf("identifiers.shikimori_id = %v, want %d (the canned candidate's anchor)", ids["shikimori_id"], qaRelayAnimeID)
	}
	// The executor stamp: the consuming run's fetch entry reads executor
	// "client" — the fetch ran on the relay, not server-side.
	okStage := qaRelayStage(doc.Stages, "ok")
	if okStage == nil {
		t.Fatalf("no ok shikimori stage in _stages %v (the notified derivation must have consumed the relay)", doc.Stages)
	}
	if got := asyncStr(okStage, "executor"); got != "client" {
		t.Errorf("ok stage executor = %q, want client (the consult hit's audit stamp)", got)
	}
	// The deferred entry survives beside it — the audit shows BOTH where the
	// fetch was handed off and where it was answered.
	if qaRelayStage(doc.Stages, "deferred") == nil {
		t.Errorf("deferred shikimori stage vanished after completion: %v (the audit must keep the handoff entry)", doc.Stages)
	}
	// The lifecycle never regressed: still ready after the re-derivation.
	sr2, status, errCode := qaSerialGetSeries(t, client, srv.baseURL, qaRelayAdminToken, sr.ID)
	if status != http.StatusOK {
		t.Fatalf("GET /series/%s after completion: HTTP %d (%s)", sr.ID, status, errCode)
	}
	if sr2.Status != "ready" {
		t.Errorf("series status = %q after the completed relay, want ready (no lifecycle regression)", sr2.Status)
	}

	// --- the ledger row cleared (reset-on-success) ---
	qaRelayWaitFailure(t, client, srv.baseURL, qaRelayAdminToken, sr.ID, false)
}

// qaRelayWriteFixtures builds the relay-joint library: one serial directory
// with a single numbered episode (its record is the shikimori-relay target).
func qaRelayWriteFixtures(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	qaSerialMedia(t, filepath.Join(root, qaRelayEpRel))
	return root
}

// qaRelayCannedSearch is the canned shikimori search body the client answers
// with — the REAL v1 list shape the plugin's Convert decodes ([]animeEntry:
// id/name/russian/kind/status/score-as-string/episodes/aired_on/description/
// url/image.original/genre). Values are re-derived independently of every
// other suite's fixtures (no-coincidence discipline); the single candidate is
// selected deterministically.
func qaRelayCannedSearch() []map[string]any {
	return []map[string]any{{
		"id":          qaRelayAnimeID,
		"name":        qaRelayTitle,
		"russian":     "Релейный маяк",
		"kind":        "tv",
		"status":      "released",
		"score":       "7.8",
		"episodes":    12,
		"aired_on":    "2014-04-06",
		"description": "qa relay canned candidate",
		"url":         "/animes/931-relay-beacon",
		"image":       map[string]any{"original": "/images/animes/931.jpg"},
		"genre": []any{
			map[string]any{"name": "Adventure", "russian": "Приключения"},
		},
	}}
}

// qaRelayPlanSpec mirrors one descriptor plan entry (store.PlanSpec — its json
// tags ARE the wire vocabulary; body rides the base64 string encoding).
type qaRelayPlanSpec struct {
	Method         string            `json:"method"`
	URL            string            `json:"url"`
	Headers        map[string]string `json:"headers,omitempty"`
	Body           []byte            `json:"body,omitempty"`
	BinarySafe     bool              `json:"binary_safe"`
	TimeoutSeconds int               `json:"timeout_seconds"`
	MinIntervalMS  int               `json:"min_interval_ms"`
}

// qaRelayClaim is the QA-local decode of the POST /relay/claim descriptor
// ({id, purpose, plan} — the api projection of the claimed store.RelayJob).
type qaRelayClaim struct {
	ID      int64             `json:"id"`
	Purpose string            `json:"purpose"`
	Plan    []qaRelayPlanSpec `json:"plan"`
}

// qaRelayFailureRow mirrors one row of GET /enrich/failures (the admin
// observability surface the ledger-cleared assertion reads).
type qaRelayFailureRow struct {
	RowID    string `json:"row_id"`
	PluginID string `json:"plugin_id"`
	Status   string `json:"status"`
	Reason   string `json:"reason"`
	Attempts int    `json:"attempts"`
}

type qaRelayFailures struct {
	Failures []qaRelayFailureRow `json:"failures"`
}

// qaRelayWaitFailure polls the ledger listing until the (series, shikimori)
// row is PRESENT (want=true) or ABSENT (want=false) — the relayed-row landing
// and the reset-on-success clearing, both bounded. The present-poll returns
// the row; the absent-poll returns the zero row.
func qaRelayWaitFailure(t *testing.T, c *http.Client, baseURL, token, seriesID string, want bool) qaRelayFailureRow {
	t.Helper()
	deadline := time.Now().Add(qaRelayWaitTimeout)
	var found qaRelayFailureRow
	for time.Now().Before(deadline) {
		var resp qaRelayFailures
		if status := doRequest(t, c, http.MethodGet, baseURL+"/api/v1/enrich/failures", token, nil, &resp); status != http.StatusOK {
			t.Fatalf("GET /enrich/failures: HTTP %d, want 200", status)
		}
		found = qaRelayFailureRow{}
		for _, f := range resp.Failures {
			if f.RowID == seriesID && f.PluginID == "shikimori" {
				found = f
				break
			}
		}
		present := found.RowID != ""
		if present == want {
			return found
		}
		time.Sleep(probeInterval)
	}
	if want {
		var resp qaRelayFailures
		_ = doRequest(t, c, http.MethodGet, baseURL+"/api/v1/enrich/failures", token, nil, &resp)
		t.Fatalf("relayed ledger row for %s/shikimori not present within %s (failures: %+v)", seriesID, qaRelayWaitTimeout, resp.Failures)
	}
	t.Fatalf("ledger row for %s/shikimori not cleared within %s (still: %+v)", seriesID, qaRelayWaitTimeout, found)
	return qaRelayFailureRow{}
}

// qaRelayPairDevice mints a durable client token through the REAL pairing
// flow over the running server (the flow TestPairingJointFlow pins in-process):
// the unauthenticated POST /pair, the admin approve, and the device's
// single-ride wait pickup.
func qaRelayPairDevice(t *testing.T, c *http.Client, baseURL string) string {
	t.Helper()
	var created map[string]any
	if status := doRequest(t, c, http.MethodPost, baseURL+"/api/v1/pair", "", nil, &created); status != http.StatusOK {
		t.Fatalf("POST /pair: HTTP %d, want 200", status)
	}
	pairingID, _ := created["pairing_id"].(string)
	if pairingID == "" {
		t.Fatalf("POST /pair body = %v, want {pairing_id, code}", created)
	}
	var approved struct {
		PairingID string `json:"pairing_id"`
		Status    string `json:"status"`
	}
	if status := doRequest(t, c, http.MethodPost, baseURL+"/api/v1/admin/pairings/"+pairingID+"/approve", qaRelayAdminToken, nil, &approved); status != http.StatusOK {
		t.Fatalf("POST /admin/pairings/%s/approve: HTTP %d, want 200", pairingID, status)
	}
	if approved.Status != "approved" {
		t.Fatalf("approve body = %+v, want status approved", approved)
	}
	var pickup map[string]any
	if status := doRequest(t, c, http.MethodGet, baseURL+"/api/v1/pair/"+pairingID+"/wait", "", nil, &pickup); status != http.StatusOK {
		t.Fatalf("GET /pair/%s/wait: HTTP %d, want 200", pairingID, status)
	}
	deviceToken, _ := pickup["device_token"].(string)
	if deviceToken == "" {
		t.Fatalf("wait pickup = %v, want the raw device_token (the credential's single ride)", pickup)
	}
	return deviceToken
}

// qaRelayWaitShikimori polls the series document until the notified
// derivation lands sources.shikimori (the consult hit committed), then
// returns the parsed document.
func qaRelayWaitShikimori(t *testing.T, c *http.Client, baseURL, token, seriesID string) asyncDoc {
	t.Helper()
	deadline := time.Now().Add(qaRelayWaitTimeout)
	var doc asyncDoc
	for time.Now().Before(deadline) {
		doc = parseAsyncDoc(t, qaSerialSeriesDocument(t, c, baseURL, token, seriesID))
		if doc.Sources["shikimori"] != nil {
			return doc
		}
		time.Sleep(probeInterval)
	}
	t.Fatalf("sources.shikimori on series %s not landed within %s (stages: %v)", seriesID, qaRelayWaitTimeout, doc.Stages)
	return doc
}

// qaRelayStage returns the LAST _stages entry for shikimori with the given
// status (the append-only stage log keeps every entry: deferred, then ok), or
// nil when none carries it.
func qaRelayStage(stages []map[string]any, status string) map[string]any {
	var found map[string]any
	for _, s := range stages {
		if asyncStr(s, "plugin_id") == "shikimori" && asyncStr(s, "status") == status {
			found = s
		}
	}
	return found
}
